// #6a993d794918a5e83bc3231b (#c3231b) AC5, треб.3 — «התנתקות» → вход; «назад» и прямой адрес снова требуют входа (кейс AUTH-LG-008).
// spec: specs/auth-login.md (5.1) · seed: tests/seed.user.spec.ts (сохранённая сессия user).
// Запрос /auth/v1/logout ПОДМЕНЁН (204): настоящий выход scope=global отозвал бы общую сессию .qa/auth/user.json.
// Отзыв старого токена на сервере проверяет tests/user-access/logout-old-token.spec.ts (#4cfd0ae4, запуск вручную).
import { test, expect } from '../../fixtures';
import { mockAuth, LOGOUT } from '../support/auth-mocks';

const authKeys = () => Object.keys(localStorage).filter((k) => /^sb-.+-auth-token$/.test(k));

test.describe('Выход из сессии (#6a993d794918a5e83bc3231b)', () => {
  test('user: «התנתקות» → /login, токен удалён; «назад» и /candidates → снова вход @desktop @prod-safe #6a993d794918a5e83bc3231b', async ({ asUser }) => {
    const page = await asUser('user');
    const logout = await mockAuth(page, LOGOUT, { status: 204 });

    await page.goto('/');
    await expect(page.getByRole('heading', { level: 1, name: /^שלום, / })).toBeVisible();
    expect(await page.evaluate(authKeys)).toHaveLength(1);
    // Вторая страница в истории — чтобы «назад» после выхода вёл на страницу с данными, а не на about:blank.
    await page.goto('/candidates');
    await expect(page.getByRole('heading', { level: 1 }).first()).toBeVisible();

    await page.getByRole('button', { name: 'התנתקות' }).click();
    await page.waitForURL((u) => u.pathname === '/login');

    // Треб.3 «ניתוק יזום»: выход запрошен для всех сессий аккаунта (scope=global), локальная сессия удалена.
    await expect.poll(() => logout.calls.length).toBeGreaterThan(0);
    expect(logout.calls[0]).toContain('scope=global');
    await expect(page.getByRole('heading', { level: 1, name: 'כניסה לחשבון' })).toBeVisible();
    await expect(page.getByTestId('session-expired')).toHaveCount(0);
    expect(await page.evaluate(authKeys)).toEqual([]);

    // AC5 «כל גישה חוזרת לנתונים מחייבת התחברות מחדש».
    await page.goBack();
    await page.waitForURL((u) => u.pathname === '/login');
    await expect(page.getByRole('heading', { level: 1, name: 'כניסה לחשבון' })).toBeVisible();
    await expect(page.getByRole('button', { name: 'התנתקות' })).toHaveCount(0);

    await page.goto('/candidates');
    await page.waitForURL((u) => u.pathname === '/login');
    expect(await page.evaluate(() => history.state?.usr?.from)).toBe('/candidates');
    await expect(page.getByRole('button', { name: 'התנתקות' })).toHaveCount(0);
  });
});
